(function () {
  'use strict';
  // Traditional IRA projection, annual steps. Each year's contribution is deposited at the start
  // of the year and the balance grows at the expected return: balance = (balance + c) x (1 + r).
  // Contributions are capped at the 2026 limit for that year's age; the deductible share comes
  // from the IRC 219(g) phase-out (reduced limit = limit x (top of range - MAGI) / range width,
  // rounded up to the next $10, minimum $200, per IRS Pub. 590-A worksheet 1-2).
  // After tax = balance - retirement tax x (balance - nondeductible contributions).
  // Taxable comparison (new contributions only): each deductible dollar becomes (1 - current
  // tax) dollars after tax, and earnings are taxed every year at the current rate.
  // CHECKS (Node, scratch tests): $7,500/yr at 6% for 35 years from $0 = 7,500 x 1.06 x
  // (1.06^35 - 1) / 0.06 = $885,906.40; $10,000 grows to 10,000 x 1.06^35 = $76,860.87;
  // single, covered, MAGI $85,000: deductible $4,500 (7,500 x 6,000 / 10,000); MAGI $90,990
  // -> $10 raised to the $200 minimum; age 50, MFJ covered, MAGI $140,000 -> 8,600 x 9,000 /
  // 20,000 = $3,870; spouse-covered MFJ at $247,000 -> $3,750; 0% return -> balance = sum.
  // ---- 2026 IRA LIMITS (tax year 2026) ------------------------------------------------------
  // Source: IRS Notice 2025-67 (2026 cost-of-living adjustments): IRC 219(b)(5) limit $7,500,
  // age-50 catch-up $1,100; IRC 219(g) deduction phase-out ranges. MFS range is fixed by statute.
  var IRA = {
    year: 2026,
    limit: 7500,
    catchUp50: 1100,
    // Deduction phase-out when YOU are covered by a workplace plan [start, end] of MAGI
    coveredRange: { single: [81000, 91000], mfj: [129000, 149000], mfs: [0, 10000] },
    // Deduction phase-out when you are not covered but your SPOUSE is
    spouseRange: { mfj: [242000, 252000], mfs: [0, 10000] }
  };
  // --------------------------------------------------------------------------------------------

  function ageLimit(age) { return IRA.limit + (age >= 50 ? IRA.catchUp50 : 0); }

  function phaseOut(limit, magi, range) {
    if (magi <= range[0]) return limit;
    if (magi >= range[1]) return 0;
    var reduced = Math.ceil(limit * (range[1] - magi) / (range[1] - range[0]) / 10 - 1e-9) * 10;
    return Math.min(limit, Math.max(200, reduced));
  }

  // Maximum deductible traditional IRA contribution for a given age and situation.
  function deductibleLimit(age, e) {
    var lim = ageLimit(age);
    if (e.covered) return phaseOut(lim, e.magi, IRA.coveredRange[e.status]);
    if (e.spouseCovered && e.status !== 'single') return phaseOut(lim, e.magi, IRA.spouseRange[e.status]);
    return lim;
  }

  // p: age, retireAge, balance, contrib, max (bool), rate, taxNow, taxLater (decimals), elig.
  function project(p) {
    var n = p.retireAge - p.age, bal = p.balance, rows = [];
    var total = 0, deductible = 0, nondeduct = 0, saved = 0, capped = false;
    var iraNew = 0, taxable = 0, taxableRate = p.rate * (1 - p.taxNow);
    for (var y = 0; y < n; y++) {
      var age = p.age + y, lim = ageLimit(age);
      var c = p.max ? lim : Math.min(p.contrib, lim);
      if (!p.max && p.contrib > lim + 0.005) capped = true;
      var d = Math.min(c, deductibleLimit(age, p.elig));
      var start = bal + c;
      bal = start * (1 + p.rate);
      iraNew = (iraNew + c) * (1 + p.rate);
      taxable = (taxable + d * (1 - p.taxNow) + (c - d)) * (1 + taxableRate);
      total += c; deductible += d; nondeduct += c - d; saved += d * p.taxNow;
      rows.push({ age: age, c: c, d: d, growth: bal - start, balance: bal });
    }
    var afterTax = bal - p.taxLater * Math.max(0, bal - nondeduct);
    var iraNewAfter = iraNew - p.taxLater * Math.max(0, iraNew - nondeduct);
    return {
      balance: bal, afterTax: afterTax, total: total, deductible: deductible, nondeduct: nondeduct,
      saved: saved, growth: bal - p.balance - total, capped: capped, rows: rows,
      iraNewAfter: iraNewAfter, taxable: taxable, years: n
    };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = Math.round(num('iraAge')), retireAge = Math.round(num('iraRetireAge')), balance = num('iraBalance'),
        contrib = num('iraContrib'), rate = num('iraRate'), taxNow = num('iraTaxNow'), taxLater = num('iraTaxLater'),
        magi = num('iraMagi'), max = document.getElementById('iraMax').checked;
    var elig = { status: document.getElementById('iraStatus').value, magi: magi,
                 covered: document.getElementById('iraCovered').checked,
                 spouseCovered: document.getElementById('iraSpouseCovered').checked };
    var error = document.getElementById('iraError');
    var bad = [age, retireAge, balance, contrib, rate, taxNow, taxLater, magi].some(isNaN) ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || balance < 0 || contrib < 0 ||
              rate < 0 || rate > 30 || taxNow < 0 || taxNow > 60 || taxLater < 0 || taxLater > 60 || magi < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 16 to 99, a retirement age above it (up to 100), non-negative amounts, ' +
                          'a return up to 30% and tax rates up to 60%.';
      return;
    }
    if (elig.status === 'single') elig.spouseCovered = false;
    var r = project({ age: age, retireAge: retireAge, balance: balance, contrib: contrib, max: max,
                      rate: rate / 100, taxNow: taxNow / 100, taxLater: taxLater / 100, elig: elig });
    set('iraFutureLabel', 'IRA balance at age ' + retireAge);
    set('iraFuture', money.format(r.balance));
    set('iraAfterTax', money.format(r.afterTax));
    set('iraContribTotal', money.format(r.total));
    set('iraGrowth', money.format(r.growth));
    set('iraTaxSaved', money.format(r.saved));
    var lim0 = ageLimit(age), ded0 = deductibleLimit(age, elig);
    set('iraFirstYear', IRA.year + ' at age ' + age + ': you can contribute up to ' + money.format(lim0) +
        ' to all your IRAs combined, and up to ' + money.format(ded0) + ' of a traditional IRA contribution is deductible.');
    var capEl = document.getElementById('iraCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('iraCapped', 'Your contribution is above the ' + IRA.year + ' limit, so it is reduced to ' +
        money.format(IRA.limit) + ' a year (' + money.format(IRA.limit + IRA.catchUp50) + ' from age 50).');
    var ndEl = document.getElementById('iraNondeduct');
    ndEl.hidden = !(r.nondeduct > 0.5);
    if (r.nondeduct > 0.5) set('iraNondeduct', 'At this income, ' + money.format(r.nondeduct) +
        ' of your contributions are not deductible. They are not taxed again when withdrawn, but their earnings are. ' +
        'Report them on Form 8606.');
    set('iraCmpIra', money.format(r.iraNewAfter));
    set('iraCmpTaxable', money.format(r.taxable));
    var diff = r.iraNewAfter - r.taxable;
    set('iraCmpDiffLabel', diff >= 0 ? 'IRA advantage' : 'Taxable account advantage');
    set('iraCmpDiff', money.format(Math.abs(diff)));
    var body = document.getElementById('iraSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.c), money.format(row.d), money.format(row.growth), money.format(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('iraForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
